/**
 * storage.js — where encrypted attachment blobs live.
 *
 * The server only ever stores ciphertext, so the storage layer is just a
 * dumb blob store. Two drivers:
 *
 *   supabase : signed upload/download URLs so the bytes go straight from the
 *              browser to Supabase and never pass through this process. The
 *              service role key stays here and is never sent to the client.
 *   local    : blobs on disk, served through this server. Handy for dev and
 *              for small single-server deployments.
 *
 * Paths are always generated by the server, never taken from the client, and
 * are validated again on read so a crafted path cannot escape the data dir.
 */

import crypto from 'node:crypto';
import fs from 'node:fs/promises';
import path from 'node:path';

const SAFE_PATH = /^att\/\d{4}\/\d{2}\/[A-Za-z0-9_-]{1,64}\/[a-f0-9]{32}$/;

/** A uid is safe to use as a filename once it matches the auth rule. */
export const isSafeUid = (uid) => typeof uid === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(uid);

/**
 * Identify an image from its leading bytes rather than trusting whatever the
 * client claimed in a header. Returns null for anything that is not an image we
 * are willing to serve back to a browser.
 */
export function sniffImageType(buffer) {
  if (!buffer || buffer.length < 12) return null;
  const bytes = Buffer.from(buffer.buffer ?? buffer, buffer.byteOffset ?? 0, Math.min(buffer.length, 16));
  if (bytes[0] === 0x89 && bytes.toString('latin1', 1, 4) === 'PNG') return 'image/png';
  if (bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) return 'image/jpeg';
  if (bytes.toString('latin1', 0, 4) === 'RIFF' && bytes.toString('latin1', 8, 12) === 'WEBP') {
    return 'image/webp';
  }
  return null;
}

export function newBlobPath(uid) {
  const now = new Date();
  const safeUid = uid.replace(/[^A-Za-z0-9_-]/g, '').slice(0, 64) || 'anon';
  const id = crypto.randomBytes(16).toString('hex');
  return `att/${now.getUTCFullYear()}/${String(now.getUTCMonth() + 1).padStart(2, '0')}/${safeUid}/${id}`;
}

export function isSafePath(p) {
  return typeof p === 'string' && SAFE_PATH.test(p);
}

/* ------------------------------------------------------------------ *
 * Supabase driver
 * ------------------------------------------------------------------ */

async function createSupabaseStorage(config) {
  const { createClient } = await import('@supabase/supabase-js');
  const client = createClient(config.secrets.supabaseUrl, config.secrets.supabaseServiceKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const bucket = config.storage.bucket;
  const avatarObject = (uid) => `avatars/${uid}`;

  return {
    driver: 'supabase',

    /* Profile photos. Deliberately NOT encrypted: a profile photo is meant to be
     * seen by everyone who can see your name, so it lives beside the bucket's
     * ciphertext blobs as an ordinary image object. */
    async putAvatar(uid, buffer, contentType) {
      const { error } = await client.storage
        .from(bucket)
        .upload(avatarObject(uid), buffer, { upsert: true, contentType });
      if (error) throw new Error(`Supabase avatar gagal: ${error.message}`);
      return { version: String(Date.now()), contentType, size: buffer.length };
    },

    async getAvatar(uid) {
      const { data, error } = await client.storage.from(bucket).download(avatarObject(uid));
      if (error || !data) return null;
      const buffer = Buffer.from(await data.arrayBuffer());
      return { buffer, contentType: sniffImageType(buffer), version: String(Date.now()) };
    },

    async removeAvatar(uid) {
      await client.storage.from(bucket).remove([avatarObject(uid)]);
    },

    async listAvatars() {
      const { data, error } = await client.storage.from(bucket).list('avatars', { limit: 1000 });
      if (error || !Array.isArray(data)) return [];
      return data
        .filter((object) => object.name && !object.name.endsWith('/'))
        .map((object) => ({ uid: object.name, version: String(Date.parse(object.updated_at) || 0) }));
    },

    async createUploadTarget(blobPath) {
      const { data, error } = await client.storage.from(bucket).createSignedUploadUrl(blobPath);
      if (error) throw new Error(`Supabase upload URL gagal: ${error.message}`);
      // The browser PUTs the raw bytes straight to Supabase.
      return { url: data.signedUrl, method: 'PUT', headers: {} };
    },

    async createDownloadUrl(blobPath, expiresInSeconds = 3600) {
      const { data, error } = await client.storage.from(bucket).createSignedUrl(blobPath, expiresInSeconds);
      if (error) throw new Error(`Supabase download URL gagal: ${error.message}`);
      return data.signedUrl;
    },

    async remove(blobPath) {
      await client.storage.from(bucket).remove([blobPath]);
    },
  };
}

/* ------------------------------------------------------------------ *
 * Local disk driver
 * ------------------------------------------------------------------ */

/**
 * Map a validated blob path onto the local data directory.
 *
 * Do NOT reach for `path.relative('/', ...)` here: path.relative resolves both
 * arguments against the current working directory, so the result silently
 * depends on where the process was started from. A plain resolve plus a
 * containment check is both correct and cwd-independent.
 */
export function resolveLocalPath(dir, blobPath) {
  const root = path.resolve(dir);
  const full = path.resolve(root, blobPath.replace(/^att\//, ''));
  if (full !== root && !full.startsWith(root + path.sep)) {
    throw new Error('Path keluar dari direktori data');
  }
  return full;
}

async function createLocalStorage(config) {
  const dir = config.storage.localDir;
  const avatarDir = config.storage.avatarDir;
  await fs.mkdir(dir, { recursive: true });

  return {
    driver: 'local',

    /* Profile photos, next to the encrypted blobs but not part of them. */
    async putAvatar(uid, buffer) {
      if (!isSafeUid(uid)) throw new Error('uid tidak valid');
      await fs.mkdir(avatarDir, { recursive: true });
      const file = path.join(avatarDir, uid);
      await fs.writeFile(file, buffer);
      const stat = await fs.stat(file);
      return { version: String(Math.round(stat.mtimeMs)), size: stat.size };
    },

    async getAvatar(uid) {
      if (!isSafeUid(uid)) return null;
      try {
        const buffer = await fs.readFile(path.join(avatarDir, uid));
        const contentType = sniffImageType(buffer);
        if (!contentType) return null;
        return { buffer, contentType, version: String(buffer.length) };
      } catch {
        return null;
      }
    },

    async removeAvatar(uid) {
      if (!isSafeUid(uid)) return;
      await fs.rm(path.join(avatarDir, uid), { force: true });
    },

    async listAvatars() {
      try {
        const names = await fs.readdir(avatarDir);
        return names.filter(isSafeUid).map((uid) => ({ uid, version: '0' }));
      } catch {
        return [];
      }
    },

    async createUploadTarget(blobPath) {
      return {
        url: `/api/blob/${blobPath}`,
        method: 'PUT',
        headers: { 'content-type': 'application/octet-stream' },
      };
    },

    async createDownloadUrl(blobPath) {
      return `/api/blob/${blobPath}`;
    },

    async save(blobPath, buffer) {
      const full = resolveLocalPath(dir, blobPath);
      await fs.mkdir(path.dirname(full), { recursive: true });
      await fs.writeFile(full, buffer);
    },

    async read(blobPath) {
      return fs.readFile(resolveLocalPath(dir, blobPath));
    },

    async remove(blobPath) {
      await fs.rm(resolveLocalPath(dir, blobPath), { force: true });
    },
  };
}

/* ------------------------------------------------------------------ *
 * Factory
 * ------------------------------------------------------------------ */

export async function createStorage(config) {
  return config.storage.driver === 'supabase'
    ? createSupabaseStorage(config)
    : createLocalStorage(config);
}
